import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Longest run of strictly rising (or falling) comparisons, skipping equal neighbours.
        int direction = 0, run = 0, best = 1;
        for (int i = 1; i < n; i++) {
            if (a[i] == a[i - 1]) continue;
            int sign = a[i] > a[i - 1] ? 1 : -1;
            run = sign == direction ? run + 1 : 1;
            direction = sign;
            best = Math.max(best, run + 1);
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Longest run of strictly rising (or falling) comparisons, skipping equal neighbours.
	direction, run, best := 0, 0, 1
	for i := 1; i < n; i++ {
		if a[i] == a[i-1] {
			continue
		}
		sign := -1
		if a[i] > a[i-1] {
			sign = 1
		}
		if sign == direction {
			run++
		} else {
			run = 1
		}
		direction = sign
		best = max(best, run+1)
	}
	fmt.Println(best)
}
